  /* ================= Юнит 1. Биография · породы VII, VIII ================= */
  notes.form7 = { title: 'Порода VII: اِنْفَعَلَ', html: `
    <p>Порода VII образуется приставкой <b>ин-</b>: <span class="ar">اِنْـ</span> + корень. Чаще всего она означает, что действие <b>случилось само</b>, без названного деятеля, — это «возвратная» пара к породе I:</p>
    <p>{{كَسَرَ الْوَلَدُ الْكُوبَ|мальчик разбил стакан}} → {{اِنْكَسَرَ الْكُوبُ|стакан разбился}}</p>
    <p>{{قَطَعَ|прервал}} → {{اِنْقَطَعَ|прервался}}, {{فَصَلَ|отделил}} → {{اِنْفَصَلَ|отделился}}</p>
    <table><tr><th></th><th>Прошедшее</th><th>Настоящее</th></tr>
    <tr><td>я</td><td>{{اِنْسَحَبْتُ|я вышел}}</td><td>{{أَنْسَحِبُ|я выхожу}}</td></tr>
    <tr><td>ты (м.)</td><td>{{اِنْسَحَبْتَ|ты вышел}}</td><td>{{تَنْسَحِبُ|ты выходишь}}</td></tr>
    <tr><td>ты (ж.)</td><td>{{اِنْسَحَبْتِ|ты вышла}}</td><td>{{تَنْسَحِبِينَ|ты выходишь}}</td></tr>
    <tr><td>он</td><td>{{اِنْسَحَبَ|он вышел}}</td><td>{{يَنْسَحِبُ|он выходит}}</td></tr>
    <tr><td>она</td><td>{{اِنْسَحَبَتْ|она вышла}}</td><td>{{تَنْسَحِبُ|она выходит}}</td></tr>
    <tr><td>мы</td><td>{{اِنْسَحَبْنَا|мы вышли}}</td><td>{{نَنْسَحِبُ|мы выходим}}</td></tr>
    <tr><td>они</td><td>{{اِنْسَحَبُوا|они вышли}}</td><td>{{يَنْسَحِبُونَ|они выходят}}</td></tr></table>
    <p><b>Масдар:</b> <span class="ar">اِنْفِعَال</span> — {{اِنْفِجَار|взрыв}}, {{اِنْطِلَاق|старт}}.</p>
    <p>Начальное <span class="ar">اِ</span> — это <b>хамза-васла</b>: внутри фразы она не читается: {{ثُمَّ انْطَلَقَ الْقِطَارُ|потом поезд отправился}}.</p>
    <p>Порода VII почти не образуется, если <b>первая</b> буква корня — <span class="ar">ء و ي ل ن ر م</span> — для них используют породу VIII.</p>` };
  notes.form8 = { title: 'Порода VIII: اِفْتَعَلَ', html: `
    <p>В породе VIII после первой буквы корня вставляется <b>т</b>: <span class="ar">اِ + ف + تَ + عَلَ</span>. Значение — возвратное, «для себя», взаимное или просто самостоятельное:</p>
    <p>{{جَمَعَ|собрал}} → {{اِجْتَمَعَ|собрался}}, {{نَشَرَ|опубликовал}} → {{اِنْتَشَرَ|распространился}}, {{كَشَفَ|раскрыл}} → {{اِكْتَشَفَ|открыл}}</p>
    <table><tr><th>Прошедшее</th><th>Настоящее</th><th>Масдар</th></tr>
    <tr><td>{{اِجْتَمَعَ|собрался}}</td><td>{{يَجْتَمِعُ|собирается}}</td><td>{{اِجْتِمَاع|собрание}}</td></tr>
    <tr><td>{{اِشْتَهَرَ|прославился}}</td><td>{{يَشْتَهِرُ|славится}}</td><td>{{اِشْتِهَار|известность}}</td></tr>
    <tr><td>{{اِخْتَارَ|выбрал}}</td><td>{{يَخْتَارُ|выбирает}}</td><td>{{اِخْتِيَار|выбор}}</td></tr></table>
    <p><b>Уподобление т.</b> Вставное <b>т</b> меняется рядом с некоторыми буквами:</p>
    <table><tr><th>Первая буква корня</th><th>Что происходит</th><th>Пример</th></tr>
    <tr><td>ص ض ط ظ</td><td>т → ط</td><td>{{اِصْطَدَمَ|столкнулся}}, {{اِضْطَرَّ|вынудил}}</td></tr>
    <tr><td>د ذ ز</td><td>т → د</td><td>{{اِزْدَادَ|увеличился}}, {{اِزْدَحَمَ|столпился}}</td></tr>
    <tr><td>و и корень أ-خ-ذ</td><td>сливается в تّ</td><td>{{اِتَّصَلَ|связался}}, {{اِتَّخَذَ|принял (решение)}}</td></tr></table>
    <p>Многие глаголы VIII требуют своего предлога: {{اِعْتَمَدَ عَلَى|полагаться на}}, {{اِلْتَحَقَ بِالْجَامِعَةِ|поступил в университет}}, {{اِشْتَهَرَ بِالشِّعْرِ|прославился стихами}}, {{اِخْتَلَفَ عَنْ|отличаться от}}.</p>` };

