  /* ================= Юнит 2. Образование · породы IX–X ================= */
  notes.form10 = { title: 'Породы X и IX', html: `
    <p><b>Порода X — اِسْتَفْعَلَ.</b> Приставка <b>ист-</b>. Основные значения:</p>
    <p>• <b>просить, искать</b> что-то: {{خَدَمَ|служил}} → {{اِسْتَخْدَمَ|использовал}}, {{أَعَارَ|одолжил}} → {{اِسْتَعَارَ|взял взаймы}}</p>
    <p>• <b>считать каким-то</b>: {{اِسْتَحْسَنَ|счёл хорошим}}</p>
    <p>• <b>стать, превратиться</b>: {{اِسْتَقَرَّ|обосновался}}</p>
    <table><tr><th></th><th>Прошедшее</th><th>Настоящее</th><th>Масдар</th></tr>
    <tr><td>правильный</td><td>{{اِسْتَخْدَمَ|использовал}}</td><td>{{يَسْتَخْدِمُ|использует}}</td><td>{{اِسْتِخْدَام|использование}}</td></tr>
    <tr><td>пустой</td><td>{{اِسْتَفَادَ|извлёк пользу}}</td><td>{{يَسْتَفِيدُ|извлекает пользу}}</td><td>{{اِسْتِفَادَة|польза}}</td></tr>
    <tr><td>удвоенный</td><td>{{اِسْتَعَدَّ|приготовился}}</td><td>{{يَسْتَعِدُّ|готовится}}</td><td>{{اِسْتِعْدَاد|подготовка}}</td></tr></table>
    <p>Обратите внимание: у удвоенных и пустых глаголов перед окончанием на согласную форма меняется: {{اِسْتَعْدَدْتُ|я приготовился}}, {{اِسْتَفَدْتُ|я извлёк пользу}}.</p>
    <p><b>Порода IX — اِفْعَلَّ.</b> Встречается почти только для <b>цветов и телесных недостатков</b>: «становиться каким-то»:</p>
    <p>{{أَحْمَرُ|красный}} → {{اِحْمَرَّ|покраснел}}, {{أَصْفَرُ|жёлтый}} → {{اِصْفَرَّ|пожелтел}}</p>
    <p>Настоящее: {{يَحْمَرُّ|краснеет}}, масдар: {{اِحْمِرَار|покраснение}}.</p>` };
  notes.formsAll = { title: 'Породы I–X: сводная таблица', html: `
    <p>Почти любой арабский глагол — это корень из трёх букв (условно <span class="ar">ف ع ل</span>), вложенный в одну из десяти «пород». Зная породу, вы знаете настоящее время, масдар и причастия.</p>
    <table><tr><th>№</th><th>Прошедшее</th><th>Настоящее</th><th>Масдар</th><th>Пример</th></tr>
    <tr><td>I</td><td>{{فَعَلَ|фа‘ала}}</td><td>{{يَفْعَلُ|йаф‘алу}}</td><td>разные</td><td>{{كَتَبَ|писал}}</td></tr>
    <tr><td>II</td><td>{{فَعَّلَ|фа‘‘ала}}</td><td>{{يُفَعِّلُ|йуфа‘‘илу}}</td><td>{{تَفْعِيل|таф‘ӣл}}</td><td>{{عَلَّمَ|учил}}</td></tr>
    <tr><td>III</td><td>{{فَاعَلَ|фа̄‘ала}}</td><td>{{يُفَاعِلُ|йуфа̄‘илу}}</td><td>{{مُفَاعَلَة|муфа̄‘ала}}</td><td>{{شَارَكَ|участвовал}}</td></tr>
    <tr><td>IV</td><td>{{أَفْعَلَ|аф‘ала}}</td><td>{{يُفْعِلُ|йуф‘илу}}</td><td>{{إِفْعَال|иф‘а̄л}}</td><td>{{أَرْسَلَ|отправил}}</td></tr>
    <tr><td>V</td><td>{{تَفَعَّلَ|тафа‘‘ала}}</td><td>{{يَتَفَعَّلُ|йатафа‘‘алу}}</td><td>{{تَفَعُّل|тафа‘‘ул}}</td><td>{{تَعَلَّمَ|учился}}</td></tr>
    <tr><td>VI</td><td>{{تَفَاعَلَ|тафа̄‘ала}}</td><td>{{يَتَفَاعَلُ|йатафа̄‘алу}}</td><td>{{تَفَاعُل|тафа̄‘ул}}</td><td>{{تَعَاوَنَ|сотрудничал}}</td></tr>
    <tr><td>VII</td><td>{{اِنْفَعَلَ|инфа‘ала}}</td><td>{{يَنْفَعِلُ|йанфа‘илу}}</td><td>{{اِنْفِعَال|инфи‘а̄л}}</td><td>{{اِنْكَسَرَ|разбился}}</td></tr>
    <tr><td>VIII</td><td>{{اِفْتَعَلَ|ифта‘ала}}</td><td>{{يَفْتَعِلُ|йафта‘илу}}</td><td>{{اِفْتِعَال|ифти‘а̄л}}</td><td>{{اِجْتَمَعَ|собрался}}</td></tr>
    <tr><td>IX</td><td>{{اِفْعَلَّ|иф‘алла}}</td><td>{{يَفْعَلُّ|йаф‘аллу}}</td><td>{{اِفْعِلَال|иф‘ила̄л}}</td><td>{{اِحْمَرَّ|покраснел}}</td></tr>
    <tr><td>X</td><td>{{اِسْتَفْعَلَ|истаф‘ала}}</td><td>{{يَسْتَفْعِلُ|йастаф‘илу}}</td><td>{{اِسْتِفْعَال|истиф‘а̄л}}</td><td>{{اِسْتَخْدَمَ|использовал}}</td></tr></table>
    <p><b>Подсказки:</b> в породах II, III, IV приставка настоящего времени огласована <b>дамой</b> (<span class="ar">يُـ</span>), во всех остальных — фатхой (<span class="ar">يَـ</span>). Породы VII–X начинаются с хамзы-васлы <span class="ar">اِ</span>.</p>` };

