  /* ================= Юнит 3. Работа и карьера · причастия ================= */
  notes.partI = { title: 'Причастия породы I: فَاعِل и مَفْعُول', html: `
    <p>От каждого глагола образуются два причастия:</p>
    <p>• <b>действительное</b> (тот, кто делает) — модель <span class="ar">فَاعِل</span>: {{كَتَبَ|писал}} → {{كَاتِب|пишущий, писатель}}</p>
    <p>• <b>страдательное</b> (то, над чем совершено действие) — модель <span class="ar">مَفْعُول</span>: {{كَتَبَ|писал}} → {{مَكْتُوب|написанный, письмо}}</p>
    <table><tr><th>Глагол</th><th>فَاعِل</th><th>مَفْعُول</th></tr>
    <tr><td>{{فَتَحَ|открыл}}</td><td>{{فَاتِح|открывающий}}</td><td>{{مَفْتُوح|открытый}}</td></tr>
    <tr><td>{{طَلَبَ|потребовал}}</td><td>{{طَالِب|требующий; студент}}</td><td>{{مَطْلُوب|требуемый}}</td></tr>
    <tr><td>{{رَفَضَ|отклонил}}</td><td>{{رَافِض|отвергающий}}</td><td>{{مَرْفُوض|отклонённый}}</td></tr>
    <tr><td>{{قَالَ|сказал}}</td><td>{{قَائِل|говорящий}}</td><td>{{مَقُول|сказанный}}</td></tr></table>
    <p>Причастия ведут себя как прилагательные: согласуются в роде и числе — {{الطَّلَبُ مَرْفُوضٌ|заявление отклонено}}, {{الْخِبْرَةُ مَطْلُوبَةٌ|опыт требуется}}, {{الطُّلَّابُ جَالِسُونَ|студенты сидят}}.</p>
    <p>Многие причастия стали обычными существительными: {{عَامِل|рабочий}}, {{مَسْؤُول|ответственное лицо}}.</p>` };
  notes.partDerived = { title: 'Причастия производных пород', html: `
    <p>В породах II–X оба причастия строятся одинаково: берём основу настоящего времени и меняем приставку на <span class="ar">مُـ</span>.</p>
    <p>• действительное — <b>кясра</b> перед последней буквой корня: {{مُدَرِّس|преподаватель}}</p>
    <p>• страдательное — <b>фатха</b> перед последней буквой: {{مُدَرَّس|преподаваемый}}</p>
    <table><tr><th>Порода</th><th>Глагол</th><th>Действит.</th><th>Страдат.</th></tr>
    <tr><td>II</td><td>{{وَظَّفَ|нанял}}</td><td>{{مُوَظِّف|наниматель}}</td><td>{{مُوَظَّف|служащий}}</td></tr>
    <tr><td>III</td><td>{{شَاهَدَ|смотрел}}</td><td>{{مُشَاهِد|зритель}}</td><td>{{مُشَاهَد|видимый}}</td></tr>
    <tr><td>IV</td><td>{{أَرْهَقَ|изнурил}}</td><td>{{مُرْهِق|изнурительный}}</td><td>{{مُرْهَق|измотанный}}</td></tr>
    <tr><td>V</td><td>{{تَدَرَّبَ|стажировался}}</td><td>{{مُتَدَرِّب|стажёр}}</td><td>—</td></tr>
    <tr><td>VIII</td><td>{{اِنْتَخَبَ|избрал}}</td><td>{{مُنْتَخِب|избиратель}}</td><td>{{مُنْتَخَب|избранный}}</td></tr>
    <tr><td>X</td><td>{{اِسْتَعْمَلَ|использовал}}</td><td>{{مُسْتَعْمِل|пользователь}}</td><td>{{مُسْتَعْمَل|подержанный}}</td></tr></table>
    <p>Одна огласовка меняет смысл: {{هٰذَا الْعَمَلُ مُرْهِقٌ|эта работа изматывает}}, но {{أَنَا مُرْهَقٌ|я измотан}}.</p>` };

