  /* ================= Юнит 4. Город и общество · пустые глаголы ================= */
  notes.hollow = { title: 'Пустые глаголы: قَالَ، بَاعَ، نَامَ', html: `
    <p>«Пустыми» называют глаголы, у которых средняя буква корня — <span class="ar">و</span> или <span class="ar">ي</span>. В словаре она превращается в долгое <b>а̄</b>: {{قَالَ|сказал}} (корень ق-و-ل), {{بَاعَ|продал}} (ب-ي-ع).</p>
    <p><b>Главное правило:</b> если после корня идёт окончание на согласную (<span class="ar">ـْتُ، ـْنَا، ـْنَ</span>) или стоит сукун, долгий гласный <b>сокращается</b>.</p>
    <table><tr><th></th><th>و: قَالَ</th><th>ي: بَاعَ</th><th>а: نَامَ</th></tr>
    <tr><td>я</td><td>{{قُلْتُ|я сказал}}</td><td>{{بِعْتُ|я продал}}</td><td>{{نِمْتُ|я спал}}</td></tr>
    <tr><td>он</td><td>{{قَالَ|он сказал}}</td><td>{{بَاعَ|он продал}}</td><td>{{نَامَ|он спал}}</td></tr>
    <tr><td>она</td><td>{{قَالَتْ|она сказала}}</td><td>{{بَاعَتْ|она продала}}</td><td>{{نَامَتْ|она спала}}</td></tr>
    <tr><td>мы</td><td>{{قُلْنَا|мы сказали}}</td><td>{{بِعْنَا|мы продали}}</td><td>{{نِمْنَا|мы спали}}</td></tr>
    <tr><td>они</td><td>{{قَالُوا|они сказали}}</td><td>{{بَاعُوا|они продали}}</td><td>{{نَامُوا|они спали}}</td></tr>
    <tr><td>настоящее</td><td>{{يَقُولُ|говорит}}</td><td>{{يَبِيعُ|продаёт}}</td><td>{{يَنَامُ|спит}}</td></tr>
    <tr><td>они (ж.)</td><td>{{يَقُلْنَ|они говорят}}</td><td>{{يَبِعْنَ|они продают}}</td><td>{{يَنَمْنَ|они спят}}</td></tr>
    <tr><td>لَمْ</td><td>{{لَمْ يَقُلْ|не сказал}}</td><td>{{لَمْ يَبِعْ|не продал}}</td><td>{{لَمْ يَنَمْ|не спал}}</td></tr>
    <tr><td>повелит.</td><td>{{قُلْ|скажи}}</td><td>{{بِعْ|продай}}</td><td>{{نَمْ|спи}}</td></tr></table>
    <p>Гласный в прошедшем «я/мы» подсказывает корень: у <span class="ar">و</span>-глаголов — <b>у</b> ({{زُرْتُ|я посетил}}), у <span class="ar">ي</span>-глаголов — <b>и</b> ({{عِشْتُ|я жил}}).</p>` };
  notes.hollowDerived = { title: 'Пустые глаголы в производных породах', html: `
    <p>В породах IV, VII, VIII и X пустые глаголы тоже «сжимают» долгий гласный перед окончанием на согласную:</p>
    <table><tr><th>Порода</th><th>Он</th><th>Я</th><th>Настоящее</th><th>لَمْ</th><th>Масдар</th></tr>
    <tr><td>IV</td><td>{{أَقَامَ|проживал}}</td><td>{{أَقَمْتُ|я проживал}}</td><td>{{يُقِيمُ|проживает}}</td><td>{{لَمْ يُقِمْ|не проживал}}</td><td>{{إِقَامَة|проживание}}</td></tr>
    <tr><td>VIII</td><td>{{اِخْتَارَ|выбрал}}</td><td>{{اِخْتَرْتُ|я выбрал}}</td><td>{{يَخْتَارُ|выбирает}}</td><td>{{لَمْ يَخْتَرْ|не выбрал}}</td><td>{{اِخْتِيَار|выбор}}</td></tr>
    <tr><td>X</td><td>{{اِسْتَفَادَ|извлёк пользу}}</td><td>{{اِسْتَفَدْتُ|я извлёк пользу}}</td><td>{{يَسْتَفِيدُ|извлекает}}</td><td>{{لَمْ يَسْتَفِدْ|не извлёк}}</td><td>{{اِسْتِفَادَة|польза}}</td></tr></table>
    <p>Повелительное наклонение тоже краткое: {{اِخْتَرْ|выбери}}, {{أَضِفْ|добавь}}; но с окончанием долгий гласный возвращается: {{اِخْتَارِي|выбери (ж.)}}, {{زُورُوا|навестите}}.</p>
    <p>Масдар породы IV от пустого корня — <span class="ar">إِفَالَة</span>: {{إِقَامَة|проживание}}, {{إِشَارَة|указание}}, {{إِضَافَة|добавление}}.</p>` };

