  notes.defPast = { title: 'Недостаточные глаголы: прошедшее время', html: `
    <p>«Недостаточными» называют глаголы, у которых <b>последняя</b> буква корня — <span class="ar">و</span> или <span class="ar">ي</span>. Есть три типа:</p>
    <table><tr><th>Тип</th><th>Словарная форма</th><th>Корень</th><th>Настоящее</th></tr>
    <tr><td>ـَا</td><td>{{دَعَا|пригласил}}</td><td>د-ع-و</td><td>{{يَدْعُو|приглашает}}</td></tr>
    <tr><td>ـَى</td><td>{{مَشَى|шёл}}</td><td>م-ش-ي</td><td>{{يَمْشِي|идёт}}</td></tr>
    <tr><td>ـِيَ</td><td>{{نَسِيَ|забыл}}</td><td>ن-س-ي</td><td>{{يَنْسَى|забывает}}</td></tr></table>
    <p><b>Прошедшее время.</b> Перед окончаниями на согласную корневая буква возвращается. У типов <span class="ar">ـَا</span> и <span class="ar">ـَى</span> она выпадает в «она» и «они», у типа <span class="ar">ـِيَ</span> — только в «они»:</p>
    <table><tr><th></th><th>دَعَا</th><th>مَشَى</th><th>نَسِيَ</th></tr>
    <tr><td>я</td><td>{{دَعَوْتُ|я пригласил}}</td><td>{{مَشَيْتُ|я шёл}}</td><td>{{نَسِيتُ|я забыл}}</td></tr>
    <tr><td>ты</td><td>{{دَعَوْتَ|ты пригласил}}</td><td>{{مَشَيْتَ|ты шёл}}</td><td>{{نَسِيتَ|ты забыл}}</td></tr>
    <tr><td>он</td><td>{{دَعَا|он пригласил}}</td><td>{{مَشَى|он шёл}}</td><td>{{نَسِيَ|он забыл}}</td></tr>
    <tr><td>она</td><td>{{دَعَتْ|она пригласила}}</td><td>{{مَشَتْ|она шла}}</td><td>{{نَسِيَتْ|она забыла}}</td></tr>
    <tr><td>мы</td><td>{{دَعَوْنَا|мы пригласили}}</td><td>{{مَشَيْنَا|мы шли}}</td><td>{{نَسِينَا|мы забыли}}</td></tr>
    <tr><td>они</td><td>{{دَعَوْا|они пригласили}}</td><td>{{مَشَوْا|они шли}}</td><td>{{نَسُوا|они забыли}}</td></tr></table>
    <p>Запомните «они»: {{دَعَوْا|они пригласили}}, {{مَشَوْا|они шли}} — с дифтонгом <b>-ав</b>, но {{نَسُوا|они забыли}} — с долгим <b>-ӯ</b>.</p>` };
  notes.defPresent = { title: 'Недостаточные глаголы: настоящее, لَمْ, أَنْ', html: `
    <p>В настоящем времени у глаголов на <span class="ar">ـُو</span> и <span class="ar">ـِي</span> окончание индикатива <b>-у</b> не видно. Главное — что происходит после <b>لَمْ</b> (и в повелительном) и после <b>أَنْ</b>:</p>
    <table><tr><th></th><th>يَدْعُو</th><th>يَمْشِي</th><th>يَنْسَى</th></tr>
    <tr><td>изъявит.</td><td>{{يَدْعُو|приглашает}}</td><td>{{يَمْشِي|идёт}}</td><td>{{يَنْسَى|забывает}}</td></tr>
    <tr><td>أَنْ</td><td>{{أَنْ يَدْعُوَ|чтобы пригласил}}</td><td>{{أَنْ يَمْشِيَ|чтобы шёл}}</td><td>{{أَنْ يَنْسَى|чтобы забыл}}</td></tr>
    <tr><td>لَمْ</td><td>{{لَمْ يَدْعُ|не пригласил}}</td><td>{{لَمْ يَمْشِ|не шёл}}</td><td>{{لَمْ يَنْسَ|не забыл}}</td></tr>
    <tr><td>повелит.</td><td>{{اُدْعُ|пригласи}}</td><td>{{اِمْشِ|иди}}</td><td>{{اِنْسَ|забудь}}</td></tr>
    <tr><td>они</td><td>{{يَدْعُونَ|приглашают}}</td><td>{{يَمْشُونَ|идут}}</td><td>{{يَنْسَوْنَ|забывают}}</td></tr></table>
    <p>После <b>لَمْ</b> и в запрете <b>لَا</b> долгий гласный на конце сокращается: {{لَا تَنْسَ|не забудь}}, {{لَمْ يَبْقَ|не остался}}.</p>
    <p>Так же ведут себя производные породы: {{يُعَانِي|страдает}} → {{لَمْ يُعَانِ|не страдал}}, {{يَتَعَافَى|выздоравливает}} → {{لَمْ يَتَعَافَ|не выздоровел}}.</p>` };

