  /* ================= Юнит 6. Покупки и экономика быта · подобные правильным и удвоенные ================= */
  notes.assim = { title: 'Подобные правильным: وَصَلَ، وَجَدَ', html: `
    <p>Если корень начинается на <span class="ar">و</span>, в настоящем времени породы I она обычно <b>выпадает</b>:</p>
    <table><tr><th>Прошедшее</th><th>Настоящее</th><th>Повелит.</th><th>Масдар</th></tr>
    <tr><td>{{وَصَلَ|прибыл}}</td><td>{{يَصِلُ|прибывает}}</td><td>{{صِلْ|прибудь}}</td><td>{{وُصُول|прибытие}}</td></tr>
    <tr><td>{{وَجَدَ|нашёл}}</td><td>{{يَجِدُ|находит}}</td><td>{{جِدْ|найди}}</td><td>{{وُجُود|наличие}}</td></tr>
    <tr><td>{{وَضَعَ|положил}}</td><td>{{يَضَعُ|кладёт}}</td><td>{{ضَعْ|положи}}</td><td>{{وَضْع|положение}}</td></tr>
    <tr><td>{{وَعَدَ|обещал}}</td><td>{{يَعِدُ|обещает}}</td><td>{{عِدْ|обещай}}</td><td>{{وَعْد|обещание}}</td></tr>
    <tr><td>{{وَثِقَ|доверял}}</td><td>{{يَثِقُ|доверяет}}</td><td>{{ثِقْ|доверяй}}</td><td>{{ثِقَة|доверие}}</td></tr></table>
    <p>В прошедшем времени — всё как у правильных глаголов: {{وَصَلْتُ|я прибыл}}, {{وَجَدْنَا|мы нашли}}.</p>
    <p>Корни на <span class="ar">ي</span> букву сохраняют: {{يَئِسَ|отчаялся}} → {{يَيْأَسُ|отчаивается}}.</p>
    <p>В производных породах <span class="ar">و</span> остаётся (породы II, III) или сливается: порода VIII — {{اِتَّفَقَ|договорился}} (из و-ف-ق), порода IV — {{أَوْصَلَ|довёз}} → {{يُوصِلُ|довозит}}.</p>` };
  notes.doubled = { title: 'Удвоенные глаголы: رَدَّ، ظَنَّ', html: `
    <p>У удвоенных глаголов вторая и третья буквы корня одинаковые и пишутся одной буквой с шаддой: {{رَدَّ|ответил}} (р-д-д).</p>
    <p><b>Правило:</b> если окончание начинается с согласной, шадда «распадается» на две буквы:</p>
    <table><tr><th></th><th>Прошедшее</th><th>Настоящее</th></tr>
    <tr><td>я</td><td>{{رَدَدْتُ|я ответил}}</td><td>{{أَرُدُّ|я отвечаю}}</td></tr>
    <tr><td>ты</td><td>{{رَدَدْتَ|ты ответил}}</td><td>{{تَرُدُّ|ты отвечаешь}}</td></tr>
    <tr><td>он</td><td>{{رَدَّ|он ответил}}</td><td>{{يَرُدُّ|он отвечает}}</td></tr>
    <tr><td>она</td><td>{{رَدَّتْ|она ответила}}</td><td>{{تَرُدُّ|она отвечает}}</td></tr>
    <tr><td>мы</td><td>{{رَدَدْنَا|мы ответили}}</td><td>{{نَرُدُّ|мы отвечаем}}</td></tr>
    <tr><td>они</td><td>{{رَدُّوا|они ответили}}</td><td>{{يَرُدُّونَ|они отвечают}}</td></tr>
    <tr><td>они (ж.)</td><td>{{رَدَدْنَ|они ответили}}</td><td>{{يَرْدُدْنَ|они отвечают}}</td></tr></table>
    <p>После <b>لَمْ</b> обычно пишут с шаддой и фатхой: {{لَمْ يَرُدَّ|не ответил}}.</p>
    <p>Гласный настоящего времени нужно запоминать: {{يَظُنُّ|думает}}, {{يَحُلُّ|решает}}, но {{يَقِلُّ|уменьшается}}.</p>` };

