  /* ================= Юнит 7. СМИ · страдательный залог ================= */
  notes.passPast = { title: 'Страдательный залог: прошедшее время', html: `
    <p>Когда важно действие, а не тот, кто его совершил, арабский использует <b>страдательный залог</b>. Деятель обычно не называется вовсе.</p>
    <p>Прошедшее время пассива породы I — модель <span class="ar">فُعِلَ</span>: <b>у — и — а</b>.</p>
    <p>{{كَتَبَ الصَّحَفِيُّ الْمَقَالَ|журналист написал статью}} → {{كُتِبَ الْمَقَالُ|статья была написана}}</p>
    <p>Бывшее дополнение становится подлежащим (именительный падеж), глагол согласуется с ним в роде: {{نُشِرَتِ الْمَقَالَةُ|статья опубликована}}.</p>
    <table><tr><th>Порода</th><th>Действит.</th><th>Страдат.</th></tr>
    <tr><td>I</td><td>{{نَشَرَ|опубликовал}}</td><td>{{نُشِرَ|был опубликован}}</td></tr>
    <tr><td>II</td><td>{{عَيَّنَ|назначил}}</td><td>{{عُيِّنَ|был назначен}}</td></tr>
    <tr><td>III</td><td>{{شَارَكَ|поделился}}</td><td>{{شُورِكَ|им поделились}}</td></tr>
    <tr><td>IV</td><td>{{أَعْلَنَ|объявил}}</td><td>{{أُعْلِنَ|было объявлено}}</td></tr>
    <tr><td>X</td><td>{{اِسْتَخْدَمَ|использовал}}</td><td>{{اُسْتُخْدِمَ|был использован}}</td></tr>
    <tr><td>пустой</td><td>{{قَالَ|сказал}}</td><td>{{قِيلَ|было сказано}}</td></tr>
    <tr><td>недостат.</td><td>{{دَعَا|пригласил}}</td><td>{{دُعِيَ|был приглашён}}</td></tr>
    <tr><td>удвоенный</td><td>{{بَثَّ|транслировал}}</td><td>{{بُثَّ|был показан}}</td></tr></table>
    <p>Правило: в пассиве все гласные основы до последней — <b>у</b>, перед последней буквой корня — <b>и</b>.</p>` };
  notes.passPresent = { title: 'Страдательный залог: настоящее время и تَمَّ', html: `
    <p>Настоящее время пассива: приставка с <b>даммой</b>, перед последней буквой корня — <b>фатха</b>: <span class="ar">يُفْعَلُ</span>.</p>
    <table><tr><th>Действит.</th><th>Страдат.</th></tr>
    <tr><td>{{يَكْتُبُ|пишет}}</td><td>{{يُكْتَبُ|пишется}}</td></tr>
    <tr><td>{{يَقْرَأُ|читает}}</td><td>{{يُقْرَأُ|читается}}</td></tr>
    <tr><td>{{يُذِيعُ|передаёт}}</td><td>{{يُذَاعُ|передаётся}}</td></tr>
    <tr><td>{{يَعْتَبِرُ|считает}}</td><td>{{يُعْتَبَرُ|считается}}</td></tr>
    <tr><td>{{يَسْتَخْدِمُ|использует}}</td><td>{{يُسْتَخْدَمُ|используется}}</td></tr>
    <tr><td>{{يَقُولُ|говорит}}</td><td>{{يُقَالُ|говорят}}</td></tr></table>
    <p>Без огласовки {{يكتب|пишет / пишется}} читается двояко — смысл подскажет контекст.</p>
    <p><b>Газетная конструкция</b> <span class="ar">تَمَّ</span> + масдар («было осуществлено…») заменяет пассив: {{تَمَّ نَشْرُ الْخَبَرِ|новость была опубликована}} = {{نُشِرَ الْخَبَرُ|новость опубликовали}}.</p>` };

