  /* ================= Юнит 8. Мнения и споры · أَنْ / أَنَّ / إِنَّ ================= */
  notes.anAnna = { title: 'أَنْ, أَنَّ или إِنَّ?', html: `
    <p>Все три слова переводятся как «что / чтобы», но употребляются по-разному.</p>
    <table><tr><th>Слово</th><th>Что после него</th><th>Пример</th></tr>
    <tr><td>{{أَنْ|ан}}</td><td>глагол в <b>сослагательной</b> форме</td><td>{{أُرِيدُ أَنْ أُنَاقِشَ الْمَوْضُوعَ|я хочу обсудить тему}}</td></tr>
    <tr><td>{{أَنَّ|анна}}</td><td>имя (в <b>винительном</b>) или местоимение-суффикс</td><td>{{أَعْتَقِدُ أَنَّ الْفِكْرَةَ جَيِّدَةٌ|считаю, что идея хорошая}}</td></tr>
    <tr><td>{{إِنَّ|инна}}</td><td>то же, но в <b>начале фразы</b> и после {{قَالَ|сказал}}</td><td>{{قَالَ إِنَّ الْوَضْعَ مُسْتَقِرٌّ|сказал, что ситуация стабильна}}</td></tr></table>
    <p>Простой тест: если дальше идёт <b>глагол</b> — почти всегда <span class="ar">أَنْ</span>. Если подлежащее и сказуемое — <span class="ar">أَنَّ</span> (или <span class="ar">إِنَّ</span> после <span class="ar">قَالَ</span>).</p>
    <p>Полезные обороты: {{يَبْدُو أَنَّ|похоже, что}}, {{مِنَ الضَّرُورِيِّ أَنْ|необходимо}}, {{مِنَ الْمُمْكِنِ أَنْ|возможно}}, {{اِعْتَرَفَ بِأَنَّهُ|признал, что он}}.</p>
    <p>С местоимениями: {{أَنَّنِي|что я}}, {{أَنَّكَ|что ты}}, {{أَنَّهُ|что он}}, {{أَنَّهَا|что она}}, {{أَنَّهُمْ|что они}}.</p>` };
  notes.innaSisters = { title: 'إِنَّ и её «сёстры»', html: `
    <p>После <span class="ar">إِنَّ / أَنَّ</span> подлежащее ставится в <b>винительный</b> падеж, а сказуемое остаётся в <b>именительном</b>:</p>
    <p>{{الْحُجَجُ مُقْنِعَةٌ|аргументы убедительны}} → {{إِنَّ الْحُجَجَ مُقْنِعَةٌ|аргументы (действительно) убедительны}}</p>
    <p>Так же ведут себя «сёстры» إِنَّ:</p>
    <table><tr><th>Частица</th><th>Значение</th><th>Пример</th></tr>
    <tr><td>{{لٰكِنَّ|но}}</td><td>но, однако</td><td>{{لٰكِنَّ الْوَقْتَ قَصِيرٌ|но времени мало}}</td></tr>
    <tr><td>{{كَأَنَّ|как будто}}</td><td>как будто</td><td>{{كَأَنَّ الْمَدِينَةَ نَائِمَةٌ|город словно спит}}</td></tr>
    <tr><td>{{لَعَلَّ|может быть}}</td><td>надежда</td><td>{{لَعَلَّ الْوَضْعَ يَتَغَيَّرُ|может, ситуация изменится}}</td></tr>
    <tr><td>{{لَيْتَ|вот бы}}</td><td>несбыточное желание</td><td>{{لَيْتَ النَّاسَ يَفْهَمُونَ|вот бы люди поняли}}</td></tr></table>
    <p>После <span class="ar">أَنْ</span> глагол — в сослагательной форме: <b>-а</b> на конце, а у форм на <span class="ar">ـُونَ / ـِينَ</span> пропадает <span class="ar">ن</span>: {{يَجِبُ أَنْ تَعْتَرِفُوا|вы должны признать}}.</p>` };

