  /* ================= Юнит 9. Мечты и планы · условные предложения ================= */
  notes.condReal = { title: 'Реальное условие: إِذَا и إِنْ', html: `
    <p><b>إِذَا</b> — «если, когда» — самое частое условное слово. После него глагол обычно в <b>прошедшем</b> времени, даже если речь о будущем:</p>
    <p>{{إِذَا دَرَسْتَ جَيِّدًا نَجَحْتَ|если будешь хорошо учиться, сдашь}}</p>
    <p>Если вторая часть начинается не с простого глагола в прошедшем, перед ней ставится <b>фа</b> <span class="ar">فَـ</span>:</p>
    <table><tr><th>Вторая часть</th><th>Пример</th></tr>
    <tr><td>будущее с سَـ</td><td>{{إِذَا جَاءَ فَسَأُخْبِرُكَ|если он придёт, я тебе скажу}}</td></tr>
    <tr><td>повелительное</td><td>{{إِذَا وَصَلْتَ فَاتَّصِلْ بِي|когда приедешь, позвони мне}}</td></tr>
    <tr><td>отрицание لَنْ / لَا</td><td>{{إِذَا نَزَلَ الْمَطَرُ فَلَنْ نَخْرُجَ|если пойдёт дождь, мы не выйдем}}</td></tr>
    <tr><td>именное предложение</td><td>{{إِذَا تَأَخَّرْتَ فَالْمُشْكِلَةُ كَبِيرَةٌ|если опоздаешь, будет большая проблема}}</td></tr></table>
    <p><b>إِنْ</b> — более книжное «если». После него оба глагола часто стоят в <b>усечённой</b> форме (как после لَمْ):</p>
    <p>{{إِنْ تَجْتَهِدْ تَنْجَحْ|если будешь стараться, добьёшься успеха}}</p>
    <p>Отрицание: {{إِنْ لَمْ تَخْرُجِ الْآنَ فَسَتَتَأَخَّرُ|если не выйдешь сейчас, опоздаешь}}.</p>` };
  notes.condLaw = { title: 'Нереальное условие: لَوْ и لَوْلَا', html: `
    <p><b>لَوْ</b> — «если бы» — для того, чего нет или не было. Обе части — в <b>прошедшем</b>, вторая обычно начинается с <span class="ar">لَـ</span>:</p>
    <p>{{لَوْ كُنْتُ غَنِيًّا لَسَافَرْتُ حَوْلَ الْعَالَمِ|если бы я был богат, я бы объехал мир}}</p>
    <p>{{لَوْ خَرَجْتَ مُبَكِّرًا لَمَا تَأَخَّرْتَ|если бы ты вышел пораньше, ты бы не опоздал}}</p>
    <p>Отрицание во второй части — <span class="ar">لَمَا</span>; в первой — <span class="ar">لَوْ لَمْ</span> + усечённая форма: {{لَوْ لَمْ يَرْبَحْ لَبَقِيَ فَقِيرًا|если бы он не выиграл, остался бы бедным}}.</p>
    <p><b>لَوْلَا</b> — «если бы не»; после него — существительное в <b>именительном</b> падеже:</p>
    <p>{{لَوْلَا دَعْمُ أُمِّي لَمَا نَجَحْتُ|если бы не мамина поддержка, я бы не добился успеха}}</p>
    <table><tr><th>Слово</th><th>Значение</th><th>Глагол</th></tr>
    <tr><td>{{إِذَا|если}}</td><td>реальное условие</td><td>прошедшее</td></tr>
    <tr><td>{{إِنْ|если}}</td><td>реальное (книжн.)</td><td>усечённая или прошедшее</td></tr>
    <tr><td>{{لَوْ|если бы}}</td><td>нереальное</td><td>прошедшее + لَـ</td></tr>
    <tr><td>{{لَوْلَا|если бы не}}</td><td>нереальное</td><td>имя + لَـ</td></tr>
    <tr><td>{{حَتَّى لَوْ|даже если}}</td><td>уступка</td><td>прошедшее</td></tr></table>` };

