  /* ================= Юнит 11. Путешествия по арабскому миру · حال и تمييز ================= */
  notes.hal = { title: 'حَال — обстоятельство образа действия', html: `
    <p><b>Халь</b> отвечает на вопрос «в каком состоянии? каким?» в момент действия. Это <b>неопределённое</b> прилагательное или причастие в <b>винительном</b> падеже:</p>
    <p>{{دَخَلَ الْمُرْشِدُ مُبْتَسِمًا|гид вошёл, улыбаясь}}</p>
    <p>{{وَصَلَ السُّيَّاحُ مُتْعَبِينَ|туристы прибыли уставшими}}</p>
    <p>Халь согласуется в роде и числе с тем, к кому относится: {{عَادَتِ الْبِنْتُ سَعِيدَةً|девочка вернулась радостной}}.</p>
    <p><b>Не путайте с определением.</b> Определение стоит в том же падеже и с той же определённостью, что и существительное; халь — всегда неопределённый и в винительном:</p>
    <table><tr><th>Определение</th><th>Халь</th></tr>
    <tr><td>{{شَرِبْتُ الْقَهْوَةَ الْبَارِدَةَ|я выпил холодный кофе}}</td><td>{{شَرِبْتُ الْقَهْوَةَ بَارِدَةً|я выпил кофе холодным}}</td></tr></table>
    <p>Халь может быть и целым предложением, обычно с <span class="ar">وَ</span>: {{خَرَجَ مِنَ الْبَيْتِ وَهُوَ يَبْكِي|он вышел из дома в слезах}}, или просто глаголом: {{رَأَيْتُ الْأَطْفَالَ يَلْعَبُونَ|я видел, как дети играют}}.</p>` };
  notes.tamyiz = { title: 'تَمْيِيز — уточнение', html: `
    <p><b>Тамйиз</b> уточняет, «в чём именно» количество или качество. Это <b>неопределённое</b> существительное в <b>винительном</b> падеже.</p>
    <table><tr><th>Где</th><th>Пример</th></tr>
    <tr><td>после чисел 11–99</td><td>{{خَمْسَةَ عَشَرَ مَتْحَفًا|пятнадцать музеев}}, {{عِشْرُونَ تِذْكَارًا|двадцать сувениров}}</td></tr>
    <tr><td>после كَمْ «сколько?»</td><td>{{كَمْ بَلَدًا زُرْتَ؟|сколько стран ты посетил?}}</td></tr>
    <tr><td>после сравнительной степени</td><td>{{أَكْثَرُ سُكَّانًا|более населённый}}, {{أَكْبَرُ سِنًّا|старше по возрасту}}</td></tr>
    <tr><td>после мер</td><td>{{كِيلُوغْرَامًا تَمْرًا|килограмм фиников}}, {{لِتْرَيْنِ حَلِيبًا|два литра молока}}</td></tr>
    <tr><td>после «наполнился» и т. п.</td><td>{{اِمْتَلَأَ الْفِنْجَانُ قَهْوَةً|чашка наполнилась кофе}}</td></tr></table>
    <p>Сравните: после <b>100, 1000</b> и чисел <b>3–10</b> — не тамйиз, а идафа с родительным: {{أَلْفُ كِيلُومِتْرٍ|тысяча километров}}, {{ثَلَاثَةُ أَيَّامٍ|три дня}}.</p>
    <p>Тамйиз помогает строить сравнительную и превосходную степень от прилагательных, у которых нет формы أَفْعَل: {{أَكْثَرُ ازْدِحَامًا|более загруженный}}, {{أَشَدُّ حَرَارَةً|более жаркий}}.</p>` };

