  /* ================= Юнит 12. Природа и экология · масдары, مفعول مطلق ================= */
  notes.masdarDerived = { title: 'Масдары производных пород', html: `
    <p>У породы I масдары приходится запоминать, а у пород II–X они строятся по моделям:</p>
    <table><tr><th>Порода</th><th>Модель</th><th>Пример</th></tr>
    <tr><td>II</td><td>{{تَفْعِيل|таф‘ӣл}}</td><td>{{لَوَّثَ|загрязнил}} → {{تَلْوِيث|загрязнение (действие)}}</td></tr>
    <tr><td>III</td><td>{{مُفَاعَلَة|муфа̄‘ала}}</td><td>{{حَافَظَ|сохранял}} → {{مُحَافَظَة|сохранение}}</td></tr>
    <tr><td>IV</td><td>{{إِفْعَال|иф‘а̄л}}</td><td>{{أَنْقَذَ|спас}} → {{إِنْقَاذ|спасение}}</td></tr>
    <tr><td>V</td><td>{{تَفَعُّل|тафа‘‘ул}}</td><td>{{تَخَلَّصَ|избавился}} → {{تَخَلُّص|избавление}}</td></tr>
    <tr><td>VI</td><td>{{تَفَاعُل|тафа̄‘ул}}</td><td>{{تَعَاوَنَ|сотрудничал}} → {{تَعَاوُن|сотрудничество}}</td></tr>
    <tr><td>VII</td><td>{{اِنْفِعَال|инфи‘а̄л}}</td><td>{{اِنْخَفَضَ|снизился}} → {{اِنْخِفَاض|снижение}}</td></tr>
    <tr><td>VIII</td><td>{{اِفْتِعَال|ифти‘а̄л}}</td><td>{{اِرْتَفَعَ|повысился}} → {{اِرْتِفَاع|повышение}}</td></tr>
    <tr><td>X</td><td>{{اِسْتِفْعَال|истиф‘а̄л}}</td><td>{{اِسْتَهْلَكَ|потреблял}} → {{اِسْتِهْلَاك|потребление}}</td></tr></table>
    <p><b>Слабые корни:</b> II недостаточный — {{غَطَّى|покрыл}} → {{تَغْطِيَة|освещение}}, {{رَبَّى|воспитал}} → {{تَرْبِيَة|воспитание}}; IV пустой — {{أَقَامَ|проживал}} → {{إِقَامَة|проживание}}; X пустой — {{اِسْتَفَادَ|извлёк пользу}} → {{اِسْتِفَادَة|польза}}.</p>
    <p>Масдар — это существительное: оно бывает подлежащим, дополнением, стоит после предлогов и в идафе: {{حِمَايَةُ الْبِيئَةِ مَسْؤُولِيَّةُ الْجَمِيعِ|защита природы — общая ответственность}}.</p>` };
  notes.mafulMutlaq = { title: 'مَفْعُول مُطْلَق — «абсолютное дополнение»', html: `
    <p>Это масдар <b>того же глагола</b> в винительном падеже. Сам по себе он лишь усиливает действие, а с прилагательным или в идафе — описывает, <b>как</b> оно совершилось:</p>
    <p>{{اِرْتَفَعَتِ الْأَسْعَارُ ارْتِفَاعًا كَبِيرًا|цены сильно выросли}} (букв. «выросли большим ростом»)</p>
    <p>{{اِنْتَظَرْتُهُ انْتِظَارًا طَوِيلًا|я долго его ждал}}</p>
    <p>{{شَكَرْتُهُ شُكْرًا جَزِيلًا|я горячо его поблагодарил}}</p>
    <table><tr><th>Глагол</th><th>Масдар (вин. п.)</th><th>Перевод</th></tr>
    <tr><td>{{اِنْخَفَضَ|снизился}}</td><td>{{اِنْخِفَاضًا حَادًّا|резко}}</td><td>резко снизился</td></tr>
    <tr><td>{{تَغَيَّرَ|изменился}}</td><td>{{تَغَيُّرًا وَاضِحًا|заметно}}</td><td>заметно изменился</td></tr>
    <tr><td>{{زَادَ|увеличился}}</td><td>{{زِيَادَةً سَرِيعَةً|быстро}}</td><td>быстро вырос</td></tr></table>
    <p>По-русски такую конструкцию почти всегда переводят наречием. Масдар должен быть именно от этого глагола: после {{تَأَثَّرَ|пострадал}} — {{تَأَثُّرًا|масдар породы V}}, а не {{تَأْثِيرًا|масдар породы II}}.</p>` };

