  /* ================= Юнит 13. Технологии · исключение ================= */
  notes.illa = { title: 'Исключение с إِلَّا', html: `
    <p><b>إِلَّا</b> — «кроме». Падеж слова после неё зависит от типа предложения.</p>
    <p><b>1. Утвердительное предложение, «из чего» исключаем — названо.</b> После إِلَّا — <b>винительный</b>:</p>
    <p>{{حَضَرَ الطُّلَّابُ إِلَّا خَالِدًا|пришли студенты, кроме Халида}}</p>
    <p>{{تَعْمَلُ الْأَجْهِزَةُ إِلَّا الطَّابِعَةَ|все устройства работают, кроме принтера}}</p>
    <p><b>2. Отрицание, «из чего» — не названо.</b> Тогда إِلَّا значит «только», а слово после неё стоит в том падеже, какой нужен по смыслу, как будто ни مَا, ни إِلَّا нет:</p>
    <table><tr><th>Пример</th><th>Роль</th><th>Падеж</th></tr>
    <tr><td>{{مَا حَضَرَ إِلَّا الْمُدِيرُ|пришёл только директор}}</td><td>подлежащее</td><td>именит.</td></tr>
    <tr><td>{{لَا أَسْتَخْدِمُ إِلَّا الْحَاسُوبَ|пользуюсь только компьютером}}</td><td>дополнение</td><td>винит.</td></tr>
    <tr><td>{{مَا هٰذَا إِلَّا بَرْنَامَجٌ|это всего лишь программа}}</td><td>сказуемое</td><td>именит.</td></tr></table>
    <p>Конструкция <span class="ar">لَا … إِلَّا</span> — самый частый способ сказать «только» в книжном стиле: {{لَا يَعْمَلُ التَّطْبِيقُ إِلَّا مَعَ الْإِنْتَرْنِتِ|приложение работает только с интернетом}}.</p>` };
  notes.ghayr = { title: 'غَيْر и سِوَى', html: `
    <p><b>غَيْر</b> и <b>سِوَى</b> тоже означают «кроме», но после них слово всегда стоит в <b>родительном</b> падеже (это идафа).</p>
    <p>{{حَضَرَ الْجَمِيعُ غَيْرَ مُحَمَّدٍ|пришли все, кроме Мухаммада}}</p>
    <p>{{لَا أَعْرِفُ لُغَةً سِوَى الْعَرَبِيَّةِ|не знаю никакого языка, кроме арабского}}</p>
    <p>Сам <span class="ar">غَيْر</span> принимает тот падеж, который получило бы слово после إِلَّا:</p>
    <table><tr><th>إِلَّا</th><th>غَيْر</th></tr>
    <tr><td>{{جَاءَ الطُّلَّابُ إِلَّا وَاحِدًا|пришли все, кроме одного}}</td><td>{{جَاءَ الطُّلَّابُ غَيْرَ وَاحِدٍ|пришли все, кроме одного}}</td></tr>
    <tr><td>{{مَا جَاءَ إِلَّا وَاحِدٌ|пришёл только один}}</td><td>{{مَا جَاءَ غَيْرُ وَاحِدٍ|пришёл только один}}</td></tr></table>
    <p><span class="ar">سِوَى</span> оканчивается на <span class="ar">ى</span>, поэтому падеж на нём не виден — это удобно.</p>
    <p>Ещё одно значение <span class="ar">غَيْر</span> — отрицательная приставка «не-»: {{غَيْرُ صَحِيحٍ|неверный}}, {{غَيْرُ صَالِحٍ|непригодный}}, {{غَيْرُ مُتَّصِلٍ|не в сети}}.</p>` };

