  notes.connectors = { title: 'Связки: как построить текст', html: `
    <p>Чтобы текст читался как единое целое, мысли соединяют связками. Их удобно учить по функциям:</p>
    <table><tr><th>Функция</th><th>Связки</th></tr>
    <tr><td>причина → следствие</td><td>{{لِأَنَّ|потому что}}, {{إِذْ|ведь}}, {{لِذٰلِكَ|поэтому}}, {{نَتِيجَةً لِذٰلِكَ|в результате}}</td></tr>
    <tr><td>противопоставление</td><td>{{لٰكِنَّ|но}}, {{إِلَّا أَنَّ|однако}}, {{غَيْرَ أَنَّ|впрочем}}, {{بِالرَّغْمِ مِنْ|несмотря на}}, {{فِي حِينِ|тогда как}}, {{بَيْنَمَا|в то время как}}</td></tr>
    <tr><td>добавление</td><td>{{كَمَا أَنَّ|к тому же}}, {{عِلَاوَةً عَلَى ذٰلِكَ|кроме того}}, {{بِالْإِضَافَةِ إِلَى|в дополнение к}}</td></tr>
    <tr><td>пример, пояснение</td><td>{{عَلَى سَبِيلِ الْمِثَالِ|например}}, {{أَيْ|то есть}}, {{بِمَعْنًى آخَرَ|другими словами}}</td></tr>
    <tr><td>структура</td><td>{{مِنْ نَاحِيَةٍ|с одной стороны}} … {{مِنْ نَاحِيَةٍ أُخْرَى|с другой стороны}}, {{فِي الْخِتَامِ|в заключение}}</td></tr></table>
    <p>Пример абзаца: {{كَانَ الْجَوُّ بَارِدًا، لِذٰلِكَ بَقِينَا فِي الْبَيْتِ|было холодно, поэтому мы остались дома}}.</p>
    <p>{{لَمْ يَكُنْ سَهْلًا، بَلْ كَانَ مُسْتَحِيلًا|это было не просто трудно — это было невозможно}}: <span class="ar">بَلْ</span> заменяет сказанное более сильным.</p>` };
  notes.connCases = { title: 'Грамматика связок', html: `
    <p>Связки различаются тем, что идёт после них.</p>
    <table><tr><th>После связки</th><th>Связки</th><th>Пример</th></tr>
    <tr><td>существительное в <b>родительном</b></td><td>{{بِالرَّغْمِ مِنْ|несмотря на}}, {{بِسَبَبِ|из-за}}, {{بِالْإِضَافَةِ إِلَى|помимо}}</td><td>{{بِالرَّغْمِ مِنَ الْمَطَرِ|несмотря на дождь}}</td></tr>
    <tr><td>имя в <b>винительном</b> (это أَنَّ!)</td><td>{{إِلَّا أَنَّ|однако}}, {{غَيْرَ أَنَّ|впрочем}}, {{كَمَا أَنَّ|к тому же}}, {{عَلَى الرَّغْمِ مِنْ أَنَّ|хотя}}</td><td>{{إِلَّا أَنَّ الظُّرُوفَ كَانَتْ صَعْبَةً|однако обстоятельства были трудными}}</td></tr>
    <tr><td>целое предложение</td><td>{{لِذٰلِكَ|поэтому}}, {{فِي حِينِ|тогда как}}, {{بَيْنَمَا|в то время как}}</td><td>{{يَعْمَلُ صَبَاحًا فِي حِينِ أَعْمَلُ مَسَاءً|он работает утром, а я вечером}}</td></tr></table>
    <p>Сравните: {{بِالرَّغْمِ مِنَ التَّعَبِ|несмотря на усталость}} — с существительным; {{بِالرَّغْمِ مِنْ أَنَّهُ مُتْعَبٌ|хотя он устал}} — с أَنَّ и предложением.</p>
    <p>Устойчивые обороты сохраняют свой падеж: {{خُلَاصَةُ الْقَوْلِ|подводя итог}}, {{مِنْ نَاحِيَةٍ أُخْرَى|с другой стороны}} (نَاحِيَة — ж. р., поэтому أُخْرَى).</p>` };

